// Compara lo que trae Tavily con lo guardado en GitHub. Solo escribe lo que cambió.
const fuentes = $('Fuentes').all().map(i => i.json);
const tav = $('Tavily: leer página').all().map(i => i.json || {});
const gh = $input.all().map(i => i.json || {});
const hoy = $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd');
const SEP = '\n<!-- contenido -->\n';
const limpiar = s => String(s || '').replace(/\r/g, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const out = [];
fuentes.forEach((f, i) => {
  const t = tav[i] || {};
  const r = (t.results || [])[0] || {};
  const nuevo = limpiar(r.raw_content).slice(0, 900000);
  if (nuevo.length < 400) {
    const motivo = ((t.failed_results || [])[0] || {}).error || t.detail || t.error || (nuevo ? 'contenido muy corto' : 'sin contenido');
    out.push({ json: { ...f, estado: 'fallo', motivo: String(typeof motivo === 'string' ? motivo : JSON.stringify(motivo)).slice(0, 160) } });
    return;
  }
  const g = gh[i] || {};
  let viejo = '';
  if (g.content) { const txt = Buffer.from(String(g.content).replace(/\n/g, ''), 'base64').toString('utf8'); viejo = limpiar(txt.includes(SEP) ? txt.split(SEP)[1] : txt); }
  if (viejo && viejo === nuevo) { out.push({ json: { ...f, estado: 'igual' } }); return; }
  const archivo = '---\ntitulo: ' + JSON.stringify(f.titulo) + '\nfuente: ' + f.url + '\narea: ' + f.area + '\nactualizado: ' + hoy + '\nnota: Copia automática de la documentación oficial. La fuente manda.\n---\n' + SEP + nuevo + '\n';
  let cambios = '';
  if (viejo) {
    const a = new Set(viejo.split('\n').map(l => l.trim()).filter(Boolean)), b = new Set(nuevo.split('\n').map(l => l.trim()).filter(Boolean));
    cambios = [...[...b].filter(l => !a.has(l)).slice(0, 40).map(l => '+ ' + l.slice(0, 300)), ...[...a].filter(l => !b.has(l)).slice(0, 25).map(l => '- ' + l.slice(0, 300))].join('\n');
    if (!cambios) { out.push({ json: { ...f, estado: 'igual' } }); return; }
  }
  out.push({ json: { ...f, estado: viejo ? 'cambio' : 'nuevo', cambios, archivo } });
});
return out;

const it = $('Comparar').all().map(i => i.json);
const n = e => it.filter(x => x.estado === e);
const nuevos = n('nuevo'), cambios = n('cambio'), fallos = n('fallo'), iguales = n('igual');
if (!nuevos.length && !cambios.length && !fallos.length) return [];
const e = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const base = 'https://github.com/__GITHUB_REPO__/blob/main/';
let t = '📖 <b>Docs oficiales de Meta y Google</b>\n' + nuevos.length + ' nuevas · ' + cambios.length + ' con cambios · ' + iguales.length + ' sin cambios · ' + fallos.length + ' sin leer';
if (cambios.length) t += '\n\n<b>Cambiaron:</b>\n' + cambios.map(c => '• <a href="' + base + c.ruta + '">' + e(c.titulo) + '</a>').join('\n');
if (nuevos.length && nuevos.length <= 8) t += '\n\n<b>Nuevas:</b>\n' + nuevos.map(c => '• ' + e(c.titulo)).join('\n');
if (fallos.length) t += '\n\n<b>No se pudieron leer:</b>\n' + fallos.map(c => '• ' + e(c.titulo) + ' — ' + e(c.motivo)).join('\n');
const pedido = cambios.length ? {
  model: 'claude-sonnet-4-5', max_tokens: 2000,
  system: 'Revisas cambios en la documentación oficial para una agencia que opera anuncios de Meta (Marketing API, Conversions API, públicos, reglas) y Google Ads con agentes en n8n. Te paso las líneas que cambiaron esta semana. Responde en español de México, máximo 150 palabras, en viñetas «- »: solo lo que afecta o podría afectar a los agentes (versiones que se retiran y fecha, campos obsoletos, límites, requisitos, políticas) y qué hay que hacer. Si nada importa, responde exactamente: «Nada que afecte a los agentes.» No inventes; si no es claro, dilo.',
  messages: [{ role: 'user', content: cambios.map(c => '## ' + c.titulo + ' (' + c.url + ')\n' + c.cambios).join('\n\n').slice(0, 60000) }],
} : null;
return [{ json: { analizar: !!pedido, texto: t, pedido } }];

const r = $('Resumen').first().json;
const j = $json || {};
const e = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const txt = Array.isArray(j.content) ? j.content.filter(c => c.type === 'text').map(c => c.text).join('\n').trim() : 'Claude no respondió: ' + JSON.stringify(j.error || j).slice(0, 200);
return [{ json: { texto: (r.texto + '\n\n<b>¿Afecta a los agentes?</b>\n' + e(txt)).slice(0, 4000) } }];

const cambios = $input.all().map(i => i.json).filter(j => j.estado === 'nuevo' || j.estado === 'cambio');
if (!cambios.length) return [];
const hoy = $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd');
return [{ json: { n: cambios.length, tree: cambios.map(c => ({ path: c.ruta, mode: '100644', type: 'blob', content: c.archivo })),
  message: 'docs-oficiales: ' + cambios.length + ' página(s) nuevas o actualizadas (' + hoy + ')\n\n' + cambios.map(c => '- ' + c.estado + ': ' + c.ruta).join('\n') } }];
